<?php
require_once __DIR__ . '/../includes/config.php';
require_once __DIR__ . '/../includes/db.php';
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/functions.php';
require_once __DIR__ . '/../includes/icons.php';

requireStudentLogin();
$pdo = getDB();
expireStaleReservations($pdo);
$student = currentStudent();

// Pending "were you also affected" requests generated by other students' complaints
$feedbackReqStmt = $pdo->prepare(
    "SELECT cf.id AS feedback_id, c.id AS complaint_id, c.description, c.complaint_type, b.bench_number
     FROM complaint_feedback cf
     JOIN complaints c ON c.id = cf.complaint_id
     LEFT JOIN benches b ON b.id = c.bench_id
     WHERE cf.student_id = ? AND cf.status = 'pending'
     ORDER BY cf.requested_at DESC"
);
$feedbackReqStmt->execute([$student['id']]);
$pendingFeedback = $feedbackReqStmt->fetchAll();

$benches = $pdo->query('SELECT id, bench_number FROM benches ORDER BY bench_number')->fetchAll();

$myComplaintsStmt = $pdo->prepare(
    "SELECT c.*, b.bench_number, s.seat_number
     FROM complaints c
     LEFT JOIN benches b ON b.id = c.bench_id
     LEFT JOIN seats s ON s.id = c.seat_id
     WHERE c.student_id = ? ORDER BY c.created_at DESC"
);
$myComplaintsStmt->execute([$student['id']]);
$myComplaints = $myComplaintsStmt->fetchAll();

$activePage = 'complaints';
$pageTitle = 'Complaints';
?>
